import{_ as s,a0 as i,w as a,s as l,ao as r,I as p,x as u,a1 as e,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在Ubuntu 13.10中给菜单添加图标 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu 13.10中给菜单添加图标 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu 13.10中给菜单添加图标 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu 13.10中给菜单添加图标 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/How to add icons to menus in Ubuntu 13.10","title":"如何在Ubuntu 13.10中给菜单添加图标","tag":"201311","desc":""},"relativePath":"201311/How to add icons to menus in Ubuntu 13.10.md","filePath":"[post].md"}'),d={name:"201311/How to add icons to menus in Ubuntu 13.10.md"};function b(m,t,T,f,g,U){const n=i("Link");return a(),l("div",null,[t[11]||(t[11]=r('<h1 id="如何在ubuntu-13-10中给菜单添加图标" tabindex="-1">如何在Ubuntu 13.10中给菜单添加图标 <a class="header-anchor" href="#如何在ubuntu-13-10中给菜单添加图标" aria-label="Permalink to “如何在Ubuntu 13.10中给菜单添加图标”">​</a></h1><p>通常，使用Ubuntu 13.10的用户会会对默认的程序、偏好和功能进行优化，才能得到更好的用户体验。</p><p>Ubuntu的用户体验是可以优化调整的，因此用户可以通过一些工具来修改和调整那些默认设置，比如使用Ubuntu Tweak。</p><p>默认情况下，Ubuntu禁用了内部菜单的图标，即，右键点击桌面打开右键菜单时，菜单中只包含文本而且没有相应的图标。</p><p>不过，在Ubuntu 13.10的菜单中添加图标是很简单的：</p><ul><li><p>安装Ubuntu Tweak</p><p>sudo add-apt-repository ppa:tualatrix/ppa</p><p>sudo apt-get update</p><p>sudo apt-get install ubuntu-tweak</p></li><li><p>启动Ubuntu Tweak，并导航到<code>Tweaks--&gt;Miscellaneous</code></p></li><li><p>选中 <code>Menus have icons</code></p></li></ul><p><strong>结果</strong>：现在右键点击桌面，图标就会在菜单中显示, 图标显示也会在其他软件的右键菜单出现(例如， Nautilus, Firefox, Gedit中的菜单等等)。</p><p><img src="http://iloveubuntu.net/pictures_me/menu%20icon%203%20ubuntu%2013.10.png" alt=""></p><p><img src="http://iloveubuntu.net/pictures_me/menu%20icons%20ubuntu%2013.10%201.png" alt=""></p><p><img src="http://iloveubuntu.net/pictures_me/menu%20icons%20ubuntu%2013.10%202.png" alt=""></p><p>这样在最常用的右键菜单中加上新增的图标，菜单会更加清晰和美丽，特别是使用单色图标菜单显示图标时。</p><hr>',12)),p("p",null,[t[1]||(t[1]=u("via: ",-1)),e(n,{href:"http://iloveubuntu.net/how-add-icons-menus-ubuntu-1310"},{default:o(()=>[...t[0]||(t[0]=[u("http://iloveubuntu.net/how-add-icons-menus-ubuntu-1310",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=u("译者：",-1)),e(n,{href:"http://blog.csdn.net/u011459130"},{default:o(()=>[...t[2]||(t[2]=[u("Yu-Fei",-1)])]),_:1}),t[5]||(t[5]=u(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[3]||(t[3]=[u("wxy",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=u("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[u("LCTT",-1)])]),_:1}),t[9]||(t[9]=u(" 原创翻译，",-1)),e(n,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[u("Linux中国",-1)])]),_:1}),t[10]||(t[10]=u(" 荣誉推出",-1))])])}const w=s(d,[["render",b]]);export{C as __pageData,w as default};
